function ValidateSearch() {
    var showNotFoundDiv = !1; $('.searchItemList').each(function () {
        if ($(this).is(":hidden")) { showNotFoundDiv = !0 }
        else { showNotFoundDiv = !1; return !1 }
    }); if (showNotFoundDiv) { $("#notFoundDiv").show() }
    else { $("#notFoundDiv").hide() }
}